//go:embed havel_prompt.txt
var havelSystemPrompt string

//go:embed havel_guide.json
var havelGuideJSON []byte

//go:embed havel_i18n.json
var havelI18nJSON []byte

// havelCatalog holds the host strings the Havel pages read (host_i18n).
var havelCatalog = hostweb.Load(havelI18nJSON)

var (
	havelGuideOnce sync.Once
	havelGuideMap  map[string]map[string]string
)

// havelGuideStrings is guide_i18n.GUIDE_STRINGS[guide_lang(lang)].
func havelGuideStrings(lang string) map[string]string {
	havelGuideOnce.Do(func() {
		if err := json.Unmarshal(havelGuideJSON, &havelGuideMap); err != nil {
			panic("havel: bad havel_guide.json: " + err.Error())
		}
	})
	if t, ok := havelGuideMap[lang]; ok {
		return t
	}
	return havelGuideMap["en"]
}

// havelGuideLang is havel.guide_lang.
func havelGuideLang(lang string) string {
	havelGuideStrings("en")
	if _, ok := havelGuideMap[lang]; ok {
		return lang
	}
	return "en"
}

