// havelSchemaJSON is havel.SCHEMA, in the Python key order, compact.
const havelSchemaJSON = `{"type":"object","additionalProperties":false,"required":["kind","reply","sources","links","action","support_summary","next"],"properties":{"kind":{"type":"string","enum":["answer","clarify","action","escalate","refuse"]},"reply":{"type":"string"},"sources":{"type":"array","items":{"type":"string"}},"links":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["page","property_id"],"properties":{"page":{"type":"string","enum":[%s]},"property_id":{"type":["integer","null"]}}}},"action":{"type":["object","null"],"additionalProperties":false,"required":["type","property_id","date_from","date_to","guests","guest_email","start_time","end_time","note"],"properties":{"type":{"type":"string","enum":["show_guest_link","create_stay","create_cleaning","sync_calendars","new_pin"]},"property_id":{"type":["integer","null"]},"date_from":{"type":["string","null"]},"date_to":{"type":["string","null"]},"guests":{"type":["integer","null"]},"guest_email":{"type":["string","null"]},"start_time":{"type":["string","null"]},"end_time":{"type":["string","null"]},"note":{"type":["string","null"]}}},"support_summary":{"type":["string","null"]},"next":{"type":"array","items":{"type":"string"}}}}`

// HavelSchema is the schema sent with every call.
func HavelSchema() json.RawMessage {
	ids := make([]string, len(havelPages))
	for i, p := range havelPages {
		ids[i] = havelPyString(p.ID)
	}
	return json.RawMessage(strings.Replace(havelSchemaJSON, "%s", strings.Join(ids, ","), 1))
}

